(() => {
 const $=s=>document.querySelector(s);
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let current=WORKFLOWS[0],selected=null,mode='native';
 const tabs=$('.scenario-tabs');
 WORKFLOWS.forEach((w,i)=>{const b=document.createElement('button');b.className='scenario-tab';b.setAttribute('role','tab');b.id=`tab-${w.id}`;b.setAttribute('aria-controls','workflow-content');b.dataset.id=w.id;b.innerHTML=`<span class="tab-top"><span class="tab-index">0${i+1}</span><span class="tab-title">${w.title}</span></span><span class="tab-sub">${w.subtitle}</span>`;b.addEventListener('click',()=>selectWorkflow(w));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?WORKFLOWS.length-1:(i+(e.key==='ArrowRight'?1:-1)+WORKFLOWS.length)%WORKFLOWS.length;selectWorkflow(WORKFLOWS[n]);tabs.children[n].focus();}});tabs.appendChild(b);});
 $('.scenario-heading').id='workflow-content';$('.scenario-heading').setAttribute('role','tabpanel');
 function selectWorkflow(w){current=w;selected=null;document.documentElement.style.setProperty('--accent',w.accent);document.documentElement.style.setProperty('--pale',w.pale);[...tabs.children].forEach(b=>{const active=b.dataset.id===w.id;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;});$('#workflow-content').setAttribute('aria-labelledby',`tab-${w.id}`);$('#scenario-meta').textContent=`${w.position} / ${w.version}`;$('#scenario-title').textContent=w.name;$('#scenario-description').textContent=w.description;$('#metrics').innerHTML=`<div class="metric"><strong>${w.nodes.length}</strong><span>Agent 任务</span></div><div class="metric"><strong>${w.edges.length}</strong><span>显式依赖</span></div>`;$('#graph-note').textContent=w.note;$('#job-detail').innerHTML=`<pre class="job-code">${esc(w.job)}</pre><p class="job-note">${esc(w.jobNote)}</p>`;$('#provenance-detail').innerHTML=[['原版',w.original],['适配',w.adapt],['待验证',w.verify]].map(([k,v])=>`<div class="provenance-row"><span>${k}</span><p>${v}</p></div>`).join('')+`<a class="source-link" href="${w.source}" target="_blank" rel="noopener noreferrer">查看固定版本源码</a>`;renderGraph();renderAgent(w.nodes[0]);}
 function renderGraph(){const w=current;$('#dag').innerHTML=`<title id="dag-title">${w.title} Workflow 的 ${w.nodes.length} 个 Agent 与 ${w.edges.length} 条依赖</title><desc id="dag-description">箭头从前驱指向后继。点击节点或用 Tab 和回车查看职责。虚线也是必须满足的依赖。</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8b9aaf"/></marker><marker id="arrow-active" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${w.accent}"/></marker></defs>`+w.edges.map(([a,b,points,cross,tag])=>{let related=!selected||a===selected||b===selected;return `<path data-edge="${a}-${b}" class="dag-edge${cross?' cross':''}${selected?(related?' highlight':' dim'):''}" d="${points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ')}" marker-end="url(#${selected&&related?'arrow-active':'arrow'})"><title>${a} → ${b}：${w.nodes.find(n=>n.id===a).title}完成后，${w.nodes.find(n=>n.id===b).title}才能开始</title></path>${cross?`<path class="edge-shaft" d="M ${points.at(-1)[0]===points.at(-2)[0]?points.at(-1)[0]:points.at(-1)[0]-18*Math.sign(points.at(-1)[0]-points.at(-2)[0])} ${points.at(-1)[1]===points.at(-2)[1]?points.at(-1)[1]:points.at(-1)[1]-18*Math.sign(points.at(-1)[1]-points.at(-2)[1])} L ${points.at(-1).join(' ')}" fill="none" stroke="${selected&&related?w.accent:'#8b9aaf'}" stroke-width="${selected&&related?2.6:1.8}" opacity="${related?1:.16}"/>`:''}${tag?`<text class="edge-tag" x="${tag[0]}" y="${tag[1]}" text-anchor="middle" opacity="${related?1:.25}">${a} → ${b}</text>`:''}`}).join('')+w.nodes.map(n=>`<g class="dag-node${selected===n.id?' selected':''}" data-node="${n.id}" tabindex="0" role="button" aria-pressed="${selected===n.id}" aria-label="${n.id} ${n.title}；前驱 ${n.pred.join('、')||'无'}；查看详情"><rect x="${n.x}" y="${n.y}" width="160" height="72" rx="8"/><text class="node-letter" x="${n.x+13}" y="${n.y+25}">${n.id}</text><text class="node-title" x="${n.x+38}" y="${n.y+26}">${n.title}</text><text class="node-pred" x="${n.x+13}" y="${n.y+53}">前驱：${n.pred.join(' · ')||'无'}</text></g>`).join('');$('#dag').querySelectorAll('[data-node]').forEach(g=>{const choose=()=>{const id=g.dataset.node;selected=id;renderGraph();renderAgent(w.nodes.find(n=>n.id===id));$('#dag').querySelector(`[data-node="${id}"]`).focus({preventScroll:true});};g.addEventListener('click',choose);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});});}
 function renderAgent(n){$('#agent-detail').innerHTML=`<div class="agent-kicker"><span class="agent-letter">${n.id}</span><div><h3>${n.title}</h3><p style="font-size:12px">${n.original}</p></div></div><div><p>${n.role}</p><div class="detail-label">执行前驱</div>${n.pred.length?n.pred.map(id=>`<span class="dependency-chip">${id} ${current.nodes.find(x=>x.id===id).title}</span>`).join(''):'<p>入口 Agent，无执行前驱。</p>'}</div><div><div class="detail-label">输入 CONTEXT · 适配示例</div><p>${n.context}</p><div class="detail-label">输出产物</div><p class="artifact">${n.output}</p></div><div><div class="detail-label">请求内容 · 适配示例</div><p>${n.prompt}</p></div><div class="node-actions"><a href="${current.id}.drawio" download>下载可编辑依赖图</a></div>`;}
 $('#reset-node').addEventListener('click',()=>{selected=null;renderGraph();renderAgent(current.nodes[0]);});
 function renderExecution(){if(mode==='native'){$('#execution-detail').innerHTML=`<div class="execution-card"><div><h3>保留自然发生的调用行为</h3><p>保留模板职责、工具使用和终止逻辑。不同角色可能是单次生成，也可能在工具返回后继续调用。将轮数作为观测结果。</p><p class="execution-footnote">最大轮数是上限，不是多轮保证。一次回复中并行调用多个工具，也不等于多次模型请求。</p></div><div class="round-list"><div class="round"><b>输入</b>当前 Job + 当前 Agent 可见的前驱产物</div><div class="round"><b>调用</b>模型生成结果；若调用工具，则等待工具返回并追加消息</div><div class="round"><b>结束</b>Agent 形成最终产物，释放依赖它的后继</div></div></div>`;}else{$('#execution-detail').innerHTML=`<div class="execution-card"><div><h3>在一个 Agent 内完成生成与修订</h3><p>采用 Self-Refine 式机制：生成初稿、检查当前任务要求、根据反馈修订。内部调用共享该 Agent 的历史，并按任务停止规则结束。</p><p class="execution-footnote">这是拟加入的适配，不是三套模板的原生行为或已执行 trace。保持消息追加并核验 token 前缀；同一 Agent 名称本身不保证 KV 可复用。</p></div><div class="round-list"><div class="round"><b>调用 1</b>“基于当前 context 完成本角色任务，给出初稿。”</div><div class="round"><b>调用 2</b>“检查上一版是否满足任务要求，指出具体问题。”</div><div class="round"><b>调用 3…</b>“依据检查结果修订；按停止规则决定继续或结束。”</div></div></div>`;}document.querySelectorAll('.mode').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});}
 document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;renderExecution();}));
 $('#source-list').innerHTML=SOURCES.map(([name,url,note],i)=>`<article class="source-item"><span class="source-number">${String(i+1).padStart(2,'0')}</span><div><a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a><p>${note}</p></div></article>`).join('');
 selectWorkflow(current);renderExecution();
})();
